// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

/**
 * The sparse-long join kernel enumerates up to 64 factors, so every factor-ordinal mask derived from it must be 64-bit
 * safe: an {@code int} shift by 33 aliases factor 33 onto factor 1 and manufactures spurious hypergraph bridges.
 */
class PackedFactorMaskWidthTest {

	@Test
	void accessEnablingMaskMustNotAliasHighOrdinalsOntoLowOrdinals() {
		long mask = PackedJoinEnumerator.accessEnablingFactorMask(34, ordinal -> ordinal == 0 || ordinal == 33);
		assertEquals(1L | 1L << 33, mask, "factors 0 and 33 are access-enabling: mask=" + Long.toBinaryString(mask));
		assertEquals(0L, mask & 1L << 1, "factor 33 must not alias factor 1");
	}

	@Test
	void accessEnablingMaskMustAddressTheLastSparseLongOrdinal() {
		long mask = PackedJoinEnumerator.accessEnablingFactorMask(64, ordinal -> ordinal == 63);
		assertEquals(1L << 63, mask, "factor 63 owns the sign bit: mask=" + Long.toBinaryString(mask));
	}

	@Test
	void accessEnablingMaskStaysExactWithinTheDenseKernel() {
		long mask = PackedJoinEnumerator.accessEnablingFactorMask(16, ordinal -> ordinal % 2 == 0);
		assertEquals(0x5555L, mask);
	}
}
